/* Delivery notes, customer ledgers and multi-invoice receipt vouchers. */
const acctRoutes=new Set(['Delivery notes','Delivery note entry','Delivery print','Delivery settings','Outstanding','Party ledger','Payment vouchers','New payment voucher','Payment voucher details']);
const acctState={editingDeliveryId:null,currentDeliveryId:null,ledgerPartyName:'',ledgerFrom:'',ledgerTo:'',voucherPartyName:''};
const acctUID=()=>window.crypto?.randomUUID?.()||`acct-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const acctEsc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const acctMoney=value=>'₹'+Number(value||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
const acctReadArray=key=>{try{const value=JSON.parse(readScopedCompany(key)||'[]');return Array.isArray(value)?value:[]}catch{return[]}};
const acctWriteArray=(key,value)=>writeScopedCompany(key,value);
function acctDeliverySettings(){try{const stored=JSON.parse(readScopedCompany('deliverySettings')||'{}');if(Number(stored.pageMargin)===10&&!stored.marginControlVersion){stored.pageMargin=5;stored.marginControlVersion=1;writeScopedCompany('deliverySettings',stored)}return{...{prefix:'DN/',nextNumber:1,pageSize:'A4',fontSize:11,pageMargin:5,marginControlVersion:1},...stored}}catch{return{prefix:'DN/',nextNumber:1,pageSize:'A4',fontSize:11,pageMargin:5,marginControlVersion:1}}}
function acctVoucherSettings(){try{return {...{prefix:'PV/',nextNumber:1},...JSON.parse(readScopedCompany('paymentVoucherSettings')||'{}')}}catch{return{prefix:'PV/',nextNumber:1}}}
function acctParties(){const rows=masterRows('parties').filter(p=>p&&p.name),seen=new Set(rows.map(p=>p.name.toLowerCase()));for(const name of [...(typeof invoices!=='undefined'?invoices.map(x=>x.party):[]),...acctReadArray('paymentVouchers').map(v=>v.party)])if(name&&!seen.has(String(name).toLowerCase())){seen.add(String(name).toLowerCase());rows.push({name:String(name)})}return rows}
function acctItems(){return masterRows('items').filter(i=>i&&i.name)}
function acctParty(name){return acctParties().find(p=>p.name===name)||{name:name||''}}
function acctInvoiceDue(x){return x?.status==='Paid'||x?.status==='Cancelled'?0:Math.max(0,Number(x?.amount||0)-Number(x?.paidAmount||0)-Number(x?.deductionAmount||0))}
function acctPartyDetails(p){return [p.gstin,p.mobile,p.phone,p.city,p.address,p.state,p.pincode,p.email].filter(Boolean).join(' · ')}
function acctPartyMatches(query){const q=String(query||'').trim().toLowerCase();return acctParties().filter(p=>!q||JSON.stringify(p).toLowerCase().includes(q)).slice(0,12)}
function acctDateISO(value){if(!value)return'';const s=String(value).trim();if(/^\d{4}-\d{2}-\d{2}$/.test(s))return s;const m=s.match(/^(\d{1,2})[\s/-]+([A-Za-z]{3,})[\s/-]+(\d{4})$/);if(m){const months=['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'],month=months.indexOf(m[2].slice(0,3).toLowerCase());if(month>=0)return`${m[3]}-${String(month+1).padStart(2,'0')}-${String(Number(m[1])).padStart(2,'0')}`}const d=new Date(s);return Number.isNaN(d.getTime())?'':d.toISOString().slice(0,10)}
function acctDisplayDate(value){const iso=acctDateISO(value);if(!iso)return String(value||'');const [y,m,d]=iso.split('-').map(Number);return new Date(y,m-1,d).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})}
function acctToday(){return new Date().toISOString().slice(0,10)}
function acctStateName(code){return stateOptions?.find(x=>x[0]===code)?.[1]||code||''}
function acctNextDeliveryNo(){const s=acctDeliverySettings();return`${s.prefix||'DN/'}${String(Number(s.nextNumber)||1).padStart(4,'0')}`}
function acctNextVoucherNo(){const s=acctVoucherSettings();return`${s.prefix||'PV/'}${String(Number(s.nextNumber)||1).padStart(4,'0')}`}
function acctPageHead(section,title,subtitle,actions=''){return`<div class="page-head"><div><div class="eyebrow">${section}</div><h1>${title}</h1><div class="subtitle">${subtitle}</div></div><div class="head-actions">${actions}</div></div>`}
function acctDeliveryPage(){const rows=acctReadArray('deliveryNotes').sort((a,b)=>acctDateISO(b.date).localeCompare(acctDateISO(a.date))),actions='<button class="btn" onclick="navigate(\'Delivery settings\')">Delivery settings</button><button class="btn primary" onclick="openDeliveryEntry()">＋ New delivery note</button>';return`${acctPageHead('SALES · DELIVERY','Delivery notes','Prepare, print and track delivery notes using saved party and item details.',actions)}<section class="card register-card"><div class="register-heading"><div><b>Saved delivery notes</b><span>Reopen a note to update dispatch details.</span></div><input type="search" placeholder="Search note, party or reference" oninput="filterDeliveryNotes(this.value)"></div><div class="table-wrap"><table><thead><tr><th>DELIVERY NOTE</th><th>DATE</th><th>PARTY</th><th>REFERENCE</th><th>ITEMS</th><th>VALUE</th><th>ACTIONS</th></tr></thead><tbody id="deliveryNoteRows">${acctDeliveryRows(rows)}</tbody></table></div></section>`}
function acctDeliveryRows(rows){return rows.map(n=>`<tr><td><b>${acctEsc(n.number)}</b></td><td>${acctEsc(acctDisplayDate(n.date))}</td><td>${acctEsc(n.party)}</td><td>${acctEsc(n.reference||'—')}</td><td>${(n.items||[]).length}</td><td class="amount">${acctMoney(n.grandTotal)}</td><td class="invoice-actions"><button onclick="openDeliveryEntry('${acctEsc(n.id)}')">Edit</button><button class="delete-action" onclick="deleteDeliveryNote('${acctEsc(n.id)}')">Delete</button></td></tr>`).join('')||'<tr><td colspan="7" class="master-no-results">No delivery notes have been saved yet.</td></tr>'}
window.filterDeliveryNotes=function(query){const q=String(query||'').toLowerCase();document.getElementById('deliveryNoteRows').innerHTML=acctDeliveryRows(acctReadArray('deliveryNotes').filter(n=>`${n.number} ${n.party} ${n.reference||''} ${n.ewaybill||''}`.toLowerCase().includes(q)))};
function acctItemOptions(selected){return`<option value="">Choose item</option>${acctItems().map(i=>`<option value="${acctEsc(i.id)}" ${i.id===selected?'selected':''}>${acctEsc(i.name)}${i.hsn?' · HSN '+acctEsc(i.hsn):''}</option>`).join('')}`}
function acctDeliveryItemRow(item={}){return`<tr class="delivery-line"><td><select class="dn-item" required onchange="fillDeliveryItem(this)">${acctItemOptions(item.itemId)}</select></td><td><input class="dn-hsn" value="${acctEsc(item.hsn||'')}" aria-label="HSN or SAC"></td><td><input class="dn-qty" type="number" min="0.01" step="0.01" value="${Number(item.quantity||1)}" oninput="updateDeliveryTotals()" required></td><td><input class="dn-unit" value="${acctEsc(item.unit||'')}" aria-label="Unit"></td><td><input class="dn-rate" type="number" min="0" step="0.01" value="${Number(item.rate||0)}" oninput="updateDeliveryTotals()" required></td><td><input class="dn-gst" type="number" min="0" max="100" step="0.01" value="${Number(item.gst||0)}" oninput="updateDeliveryTotals()" aria-label="GST rate"></td><td class="dn-line-amount">${acctMoney(item.amount||0)}</td><td><button class="remove-line" type="button" onclick="this.closest('tr').remove();updateDeliveryTotals()" aria-label="Remove item">×</button></td></tr>`}
window.fillDeliveryItem=function(select){const item=acctItems().find(x=>x.id===select.value),row=select.closest('tr');if(!row||!item)return;row.querySelector('.dn-hsn').value=item.hsn||'';row.querySelector('.dn-unit').value=item.unit||'';row.querySelector('.dn-rate').value=Number(item.rate||0);row.querySelector('.dn-gst').value=Number(item.gst||0);updateDeliveryTotals()};
window.updateDeliveryTotals=function(){let taxable=0,tax=0;document.querySelectorAll('.delivery-line').forEach(row=>{const base=Number(row.querySelector('.dn-qty')?.value||0)*Number(row.querySelector('.dn-rate')?.value||0),gst=base*Number(row.querySelector('.dn-gst')?.value||0)/100;taxable+=base;tax+=gst;const amount=row.querySelector('.dn-line-amount');if(amount)amount.textContent=acctMoney(base)});const set=(id,value)=>{const el=document.getElementById(id);if(el)el.textContent=acctMoney(value)};set('dnTaxableTotal',taxable);set('dnGSTTotal',tax);set('dnGrandTotal',taxable+tax)};
function openDeliveryEntry(id=''){acctState.editingDeliveryId=id||null;page='Delivery note entry';render()}
window.openDeliveryEntry=openDeliveryEntry;
window.printSavedDeliveryNote=function(id){acctState.currentDeliveryId=id;page='Delivery print';document.body.classList.add('acct-delivery-print-mode');window.addEventListener('afterprint',()=>document.body.classList.remove('acct-delivery-print-mode'),{once:true});render();setTimeout(()=>window.print(),120)};window.shareSavedDeliveryNote=function(id){const n=acctReadArray('deliveryNotes').find(x=>x.id===id);if(!n)return;acctState.currentDeliveryId=id;page='Delivery print';document.body.classList.add('acct-delivery-print-mode');render();setTimeout(()=>window.sharePrintPdfToWhatsApp('Delivery-Challan-'+n.number,acctParty(n.party).mobile||'').finally(()=>document.body.classList.remove('acct-delivery-print-mode')),120)};
function acctDeliveryEntryPage(){const note=acctReadArray('deliveryNotes').find(n=>n.id===acctState.editingDeliveryId)||{},company=readCompany(),settings=acctDeliverySettings(),party=note.party||'',lines=note.items?.length?note.items:[{}],partyOptions=acctParties().map(p=>`<option value="${acctEsc(p.name)}" ${party===p.name?'selected':''}>${acctEsc(p.name)} · ${acctEsc(p.gstin||p.mobile||p.city||'')}</option>`).join('');return`${acctPageHead('SALES · DELIVERY','Delivery note entry','Record the goods delivered, recipient and dispatch references.')}<form class="card dn-entry" onsubmit="saveDeliveryNote(event)"><div class="entry-top"><div class="section-heading"><b>Delivery details</b><span>Delivery notes do not create an invoice or change party balances.</span></div><div class="dn-entry-meta"><div class="field"><label>Delivery note number *</label><input name="number" required value="${acctEsc(note.number||acctNextDeliveryNo())}"></div><div class="field"><label>Date *</label><input name="date" type="date" required value="${acctEsc(acctDateISO(note.date)||acctToday())}"></div><div class="field"><label>Reference no.</label><input name="reference" value="${acctEsc(note.reference||'')}"></div></div></div><div class="dn-party-grid"><div class="field"><label>Party / recipient *</label><select name="party" required><option value="">Choose party</option>${partyOptions}</select></div><div class="field"><label>Place of supply</label><select name="placeOfSupply"><option value="">Use party state</option>${stateOptions.map(([code,name])=>`<option value="${code}" ${note.placeOfSupply===code?'selected':''}>${acctEsc(name)} (${code})</option>`).join('')}</select></div></div><div class="dn-party-hint">Choose a party from your master. Its address and GSTIN will appear on the printed note.</div><div class="panel-head dn-items-head"><div><div class="panel-title">Items delivered</div><div class="panel-note">Item, quantity, unit, rate and GST are filled from the item master and can be adjusted for this note.</div></div><button type="button" class="btn" onclick="addDeliveryLine()">＋ Add item</button></div><div class="table-wrap dn-table-wrap"><table class="dn-table"><thead><tr><th>ITEM / DESCRIPTION</th><th>HSN/SAC</th><th>QTY</th><th>PER</th><th>RATE</th><th>GST %</th><th>AMOUNT</th><th></th></tr></thead><tbody id="deliveryLines">${lines.map(acctDeliveryItemRow).join('')}</tbody></table></div><div class="dn-total-card"><div><span>Taxable value</span><b id="dnTaxableTotal">${acctMoney(note.taxable||0)}</b></div><div><span>GST</span><b id="dnGSTTotal">${acctMoney(note.tax||0)}</b></div><div class="dn-grand"><span>Total value</span><b id="dnGrandTotal">${acctMoney(note.grandTotal||0)}</b></div></div><div class="setup-section"><div class="setup-section-title"><b>Transport and notes</b><span>Optional dispatch and receipt details</span></div><div class="setup-grid"><div class="field"><label>Transporter</label><input name="transporter" value="${acctEsc(note.transporter||'')}"></div><div class="field"><label>Vehicle number</label><input name="vehicle" value="${acctEsc(note.vehicle||'')}"></div><div class="field"><label>LR / RR number</label><input name="lrNumber" value="${acctEsc(note.lrNumber||'')}"></div><div class="field"><label>e-Way bill number</label><input name="ewaybill" value="${acctEsc(note.ewaybill||'')}"></div><div class="field full"><label>Delivery instructions / remarks</label><textarea name="remarks">${acctEsc(note.remarks||'')}</textarea></div></div></div><div class="settings-footer"><button class="btn" type="button" onclick="navigate('Delivery notes')">Cancel</button><button class="btn primary" type="submit">${note.id?'Save changes':'Save delivery note'}</button>${note.id?`<button class="btn" type="button" onclick="printSavedDeliveryNote('${acctEsc(note.id)}')">Print challan</button><button class="btn whatsapp-reminder-btn" type="button" onclick="shareSavedDeliveryNote('${acctEsc(note.id)}')">Share PDF to WhatsApp</button>`:''}</div></form>`}
window.addDeliveryLine=function(itemId=''){const host=document.getElementById('deliveryLines');if(!host)return;host.insertAdjacentHTML('beforeend',acctDeliveryItemRow({itemId}));if(itemId){const select=host.lastElementChild.querySelector('.dn-item');fillDeliveryItem(select)}updateDeliveryTotals()};
window.saveDeliveryNote=function(event){event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const data=new FormData(form),party=String(data.get('party')||''),lines=[...document.querySelectorAll('.delivery-line')].map(row=>({itemId:row.querySelector('.dn-item').value,name:acctItems().find(i=>i.id===row.querySelector('.dn-item').value)?.name||row.querySelector('.dn-item').selectedOptions[0]?.textContent||'',hsn:row.querySelector('.dn-hsn').value.trim(),quantity:Number(row.querySelector('.dn-qty').value||0),unit:row.querySelector('.dn-unit').value.trim(),rate:Number(row.querySelector('.dn-rate').value||0),gst:Number(row.querySelector('.dn-gst').value||0)})).filter(x=>x.itemId&&x.quantity>0);if(!lines.length){toast('Add at least one item before saving');return}let taxable=0,tax=0;for(const line of lines){line.taxable=Number((line.quantity*line.rate).toFixed(2));line.taxAmount=Number((line.taxable*line.gst/100).toFixed(2));line.amount=line.taxable;taxable+=line.taxable;tax+=line.taxAmount}const old=acctReadArray('deliveryNotes'),index=old.findIndex(x=>x.id===acctState.editingDeliveryId),settings=acctDeliverySettings(),note={...(index>=0?old[index]:{}),id:acctState.editingDeliveryId||acctUID(),number:String(data.get('number')).trim(),date:String(data.get('date')),party,placeOfSupply:String(data.get('placeOfSupply')||acctParty(party).state||''),shippingAddress:String(data.get('shippingAddress')||''),reference:String(data.get('reference')||'').trim(),transporter:String(data.get('transporter')||'').trim(),vehicle:String(data.get('vehicle')||'').trim(),lrNumber:String(data.get('lrNumber')||'').trim(),ewaybill:String(data.get('ewaybill')||'').trim(),remarks:String(data.get('remarks')||'').trim(),items:lines,taxable:Number(taxable.toFixed(2)),tax:Number(tax.toFixed(2)),grandTotal:Number((taxable+tax).toFixed(2)),updatedAt:new Date().toISOString()};if(index>=0)old[index]=note;else{old.unshift(note);settings.nextNumber=Number(settings.nextNumber||1)+1;writeScopedCompany('deliverySettings',settings)}acctWriteArray('deliveryNotes',old);acctState.editingDeliveryId=note.id;page='Delivery note entry';render();toast('Delivery note saved')};
window.deleteDeliveryNote=function(id){const rows=acctReadArray('deliveryNotes'),note=rows.find(n=>n.id===id);if(!note||!confirm(`Delete delivery note ${note.number}?`))return;acctWriteArray('deliveryNotes',rows.filter(n=>n.id!==id));render();toast('Delivery note deleted')};

function acctDeliverySettingsPage(){const s=acctDeliverySettings(),fontSize=Number(s.fontSize)||11,pageMargin=Number(s.pageMargin)||5;return `${acctPageHead('SETTINGS · DELIVERY','Delivery settings','Set the delivery challan paper size, print font and page margins.')}<form class="card setup-form" onsubmit="saveDeliverySettings(event)"><div class="setup-section"><div class="setup-section-title"><b>Print layout</b><span>These settings apply to the delivery challan preview and print.</span></div><div class="setup-grid"><div class="field"><label>Paper size</label><select name="pageSize"><option ${s.pageSize==='A4'?'selected':''}>A4</option><option ${s.pageSize==='A5'?'selected':''}>A5</option><option ${s.pageSize==='A6'?'selected':''}>A6</option></select></div><div class="field"><label>Print font size (pt)</label><select name="fontSize">${[9,10,11,12,13,14,15,16].map(x=>`<option value="${x}" ${fontSize===x?'selected':''}>${x} pt</option>`).join('')}</select></div><div class="field"><label>Page margin (mm)</label><select name="pageMargin">${[3,5,8,10,12,15,18].map(x=>`<option value="${x}" ${pageMargin===x?'selected':''}>${x} mm</option>`).join('')}</select></div></div></div><div class="setup-section"><div class="setup-section-title"><b>Numbering</b><span>New delivery notes use this prefix and next sequence number.</span></div><div class="setup-grid"><div class="field"><label>Delivery note prefix</label><input name="prefix" value="${acctEsc(s.prefix)}"></div><div class="field"><label>Next number</label><input name="nextNumber" type="number" min="1" step="1" value="${Number(s.nextNumber)||1}"></div></div></div><div class="settings-footer"><button class="btn primary" type="submit">Save delivery settings</button></div></form>`}
window.saveDeliverySettings=function(event){event.preventDefault();const data=new FormData(event.currentTarget),s=acctDeliverySettings();s.pageSize=String(data.get('pageSize')||'A4');s.fontSize=Math.min(16,Math.max(9,Number(data.get('fontSize'))||11));s.pageMargin=Math.min(18,Math.max(3,Number(data.get('pageMargin'))||5));s.marginControlVersion=1;s.prefix=String(data.get('prefix')||'DN/').trim();s.nextNumber=Math.max(1,Number(data.get('nextNumber'))||1);writeScopedCompany('deliverySettings',s);render();toast('Delivery settings saved')};function acctNumberWords(amount){let n=Math.round(Number(amount)||0);if(!n)return'Zero';const one=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'],tens=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'],under100=x=>x<20?one[x]:tens[Math.floor(x/10)]+(x%10?' '+one[x%10]:''),under1000=x=>(x>=100?one[Math.floor(x/100)]+' Hundred'+(x%100?' '+under100(x%100):''):under100(x)),parts=[];for(const [unit,div] of [['Arab',1000000000],['Crore',10000000],['Lakh',100000],['Thousand',1000],['',1]]){const v=Math.floor(n/div);if(v){parts.push(under1000(v)+(unit?' '+unit:''));n%=div}}return parts.join(' ')}
function acctAmountWords(amount){const cents=Math.max(0,Math.round(Number(amount||0)*100)),rupees=Math.floor(cents/100),paise=cents%100;return acctNumberWords(rupees)+(paise?' and '+acctNumberWords(paise)+' Paise':'')}
function acctDeliveryPrintPage(){const n=acctReadArray('deliveryNotes').find(x=>x.id===acctState.currentDeliveryId);if(!n)return `${acctPageHead('SALES · DELIVERY','Delivery note unavailable','This note may have been removed.','<button class="btn" onclick="navigate(\'Delivery notes\')">Back to delivery notes</button>')}`;const c=readCompany(),p=acctParty(n.party),place=acctStateName(n.placeOfSupply||p.state),qty=(n.items||[]).reduce((sum,x)=>sum+Number(x.quantity||0),0),head=acctPageHead('SALES · DELIVERY',`Delivery challan ${acctEsc(n.number)}`,`${acctEsc(n.party)} · ${acctEsc(acctDisplayDate(n.date))}`,'<button class="btn" onclick="navigate(\'Delivery notes\')">← Back</button><button class="btn primary" onclick="window.print()">Print</button><button class="btn whatsapp-reminder-btn" onclick="sharePrintPdfToWhatsApp(\'Delivery-Challan-${acctEsc(n.number)}\',\'${acctEsc(p.mobile||\'\')}\')">Share PDF to WhatsApp</button>'),buyerAddress=[p.address,p.city,p.pincode].filter(Boolean).join(', ');return `${head}<article class="delivery-print-sheet dn-format-classic"><h1 class="dn-document-heading">Delivery Challan</h1><h2 class="dn-document-subheading">DELIVERY NOTE</h2><section class="dn-parties-meta"><div class="dn-party-seller"><b>${acctEsc(c.name||'Company')}</b><div>${acctEsc(c.address||'')}</div><div>${acctEsc([c.city,c.pincode].filter(Boolean).join(', '))}</div>${c.phone?`<div>Phone: ${acctEsc(c.phone)}</div>`:''}${c.gstin?`<div>GSTIN/UIN: ${acctEsc(c.gstin)}</div>`:''}</div><div class="dn-meta-grid"><div><small>Delivery Note No.</small><b>${acctEsc(n.number)}</b></div><div><small>Dated</small><b>${acctEsc(acctDisplayDate(n.date))}</b></div><div><small>Supplier's Ref.</small><b>${acctEsc(n.reference||'')}</b></div><div><small>Mode/Terms of Payment</small><b></b></div><div><small>Buyer's Order No.</small><b></b></div><div><small>Dated</small><b></b></div><div><small>Despatch Document No.</small><b>${acctEsc(n.ewaybill||'')}</b></div><div><small>Dated</small><b></b></div><div><small>Despatched through</small><b>${acctEsc(n.transporter||'')}</b></div><div><small>Destination</small><b>${acctEsc(place)}</b></div></div><div class="dn-party-buyer"><small>Buyer</small><b>${acctEsc(p.name||n.party)}</b><div>${acctEsc(buyerAddress)}</div>${p.gstin?`<div>GSTIN/UIN: ${acctEsc(p.gstin)}</div>`:''}${p.state?`<div>State Name: ${acctEsc(place)}${p.state?', Code : '+acctEsc(p.state):''}</div>`:''}</div><div class="dn-delivery-terms"><small>Terms of Delivery</small><div>${acctEsc(n.remarks||'')}</div></div></section><table class="dn-print-items dn-goods-table"><thead><tr><th>Description of Goods</th><th>Quantity</th><th>Rate</th><th>per</th><th>Amount</th></tr></thead><tbody>${(n.items||[]).map(item=>`<tr class="dn-product-row"><td><b>${acctEsc(item.name)}</b></td><td class="dn-qty-cell"><b>${Number(item.quantity).toLocaleString('en-IN')} ${acctEsc(item.unit||'')}</b></td><td class="dn-num">${acctMoney(item.rate)}</td><td>${acctEsc(item.unit||'')}</td><td class="dn-num"><b>${acctMoney(item.taxable)}</b></td></tr>`).join('')}<tr class="dn-total-row"><td colspan="1">Total</td><td class="dn-qty-cell"><b>${qty.toLocaleString('en-IN')} ${acctEsc((n.items||[]).find(x=>x.unit)?.unit||'')}</b></td><td></td><td></td><td class="dn-num"><b>${acctMoney(n.taxable)}</b></td></tr></tbody></table><div class="dn-words"><small>Amount Chargeable (in words)</small><b>Rs. ${acctAmountWords(n.taxable)} Only</b></div><div class="dn-eoe">E. &amp; O.E.</div><footer class="dn-signatures"><div>Received in Good Condition</div><div><b>for ${acctEsc(c.name||'Company')}</b></div></footer></article>`}function acctLedgerSearchMenu(query){const q=String(query||'').trim(),rows=acctPartyMatches(q);return rows.map(p=>`<button type="button" class="acct-party-option" data-party="${acctEsc(p.name)}"><b>${acctEsc(p.name)}</b><small>${acctEsc(acctPartyDetails(p))}</small></button>`).join('')||'<div class="acct-party-empty">No matching party in the master.</div>'}
window.searchLedgerParty=function(value){const menu=document.getElementById('ledgerPartyOptions');if(menu){menu.innerHTML=acctLedgerSearchMenu(value);menu.hidden=false}};
window.selectLedgerParty=function(name){acctState.ledgerPartyName=name;render()};
function acctLedgerTransactions(party){const entries=[],vouchers=acctReadArray('paymentVouchers'),used={};for(const x of invoices){if(x.party!==party||x.status==='Cancelled'||x.status==='Draft')continue;const amount=Number(x.amount||0);entries.push({date:acctDateISO(x.date),kind:'debit',label:`Invoice ${x.no}`,reference:x.no,debit:amount,credit:0,sort:0});if(Number(x.deductionAmount||0)>0)entries.push({date:acctDateISO(x.date),kind:'credit',label:`Adjustment / deduction · ${x.no}`,reference:x.no,debit:0,credit:Number(x.deductionAmount),sort:1});used[x.no]=0}for(const v of vouchers){if(v.party!==party)continue;const allocations=v.allocations||[];for(const allocation of allocations)used[allocation.invoiceNo]=(used[allocation.invoiceNo]||0)+Number(allocation.amount||0);if(Number(v.amount||0)>0)entries.push({date:acctDateISO(v.date),kind:'credit',label:`Receipt ${v.number}`,reference:v.number,debit:0,credit:Number(v.amount),sort:2})}for(const x of invoices){if(x.party!==party||x.status==='Cancelled'||x.status==='Draft')continue;const legacy=Math.max(0,Number(x.paidAmount||0)-Number(used[x.no]||0));if(legacy>0)entries.push({date:acctDateISO(x.date),kind:'credit',label:`Recorded receipt · ${x.no}`,reference:x.no,debit:0,credit:legacy,sort:1})}return entries.filter(x=>x.date).sort((a,b)=>a.date.localeCompare(b.date)||a.sort-b.sort||a.reference.localeCompare(b.reference))}
function acctLedgerPage(){const party=acctState.ledgerPartyName,p=party?acctParty(party):{},allEntries=party?acctLedgerTransactions(party):[],opening=acctState.ledgerFrom?allEntries.filter(x=>x.date<acctState.ledgerFrom).reduce((sum,x)=>sum+x.debit-x.credit,0):0,inRange=allEntries.filter(x=>(!acctState.ledgerFrom||x.date>=acctState.ledgerFrom)&&(!acctState.ledgerTo||x.date<=acctState.ledgerTo)),debit=inRange.reduce((sum,x)=>sum+x.debit,0),credit=inRange.reduce((sum,x)=>sum+x.credit,0);let balance=opening;const openingRow=party&&acctState.ledgerFrom?`<tr class="acct-opening-row"><td>${acctEsc(acctDisplayDate(acctState.ledgerFrom))}</td><td><b>Opening balance</b></td><td>—</td><td>—</td><td>—</td><td class="amount">${acctMoney(opening)}</td></tr>`:"";const body=openingRow+inRange.map(x=>{balance+=x.debit-x.credit;return`<tr><td>${acctEsc(acctDisplayDate(x.date))}</td><td>${acctEsc(x.label)}</td><td>${acctEsc(x.reference)}</td><td class="acct-debit">${x.debit?acctMoney(x.debit):'—'}</td><td class="acct-credit">${x.credit?acctMoney(x.credit):'—'}</td><td class="amount">${acctMoney(balance)}</td></tr>`}).join('')||`<tr><td colspan="6" class="master-no-results">${party?'No debit or credit entries in this date range.':'Select a party to show its ledger.'}</td></tr>`,due=party?invoices.filter(x=>x.party===party&&x.status!=='Cancelled'&&x.status!=='Draft').reduce((sum,x)=>sum+acctInvoiceDue(x),0):0,actions=party?`<button class="btn" onclick="printPartyLedger()">Print ledger</button><button class="btn whatsapp-reminder-btn" onclick="window.printPartyLedger(false,true)">Share ledger PDF to WhatsApp</button><button class="btn" onclick="openPartyLedgerReminder()">WhatsApp party reminder</button><button class="btn primary" onclick="openPaymentVoucher(this.dataset.party)" data-party="${acctEsc(party)}">＋ Payment voucher</button>`:'';return`${acctPageHead('REGISTERS · PARTY ACCOUNT','Party ledger','Review invoice debits and payment credits for any date range.',actions)}<section class="card acct-ledger-filter"><div class="acct-party-search"><label for="ledgerPartySearch">Search party by name or any saved detail</label><input id="ledgerPartySearch" type="search" value="${acctEsc(party)}" placeholder="Name, GSTIN, phone, city or address" oninput="searchLedgerParty(this.value)" onfocus="searchLedgerParty(this.value)" autocomplete="off"><div class="acct-party-options" id="ledgerPartyOptions" hidden>${acctLedgerSearchMenu(party)}</div></div><label>From <input id="ledgerFrom" type="date" value="${acctEsc(acctState.ledgerFrom)}" onchange="acctSetLedgerDates(this.value,document.getElementById('ledgerTo').value)"></label><label>To <input id="ledgerTo" type="date" value="${acctEsc(acctState.ledgerTo)}" onchange="acctSetLedgerDates(document.getElementById('ledgerFrom').value,this.value)"></label></section>${party?`<div class="acct-ledger-party card"><div><b>${acctEsc(p.name||party)}</b><span>${acctEsc(acctPartyDetails(p))}</span></div><div class="acct-ledger-due"><small>OUTSTANDING</small><b>${acctMoney(due)}</b></div></div><div class="register-summary acct-ledger-summary"><div class="card"><small>DEBIT</small><b>${acctMoney(debit)}</b></div><div class="card"><small>CREDIT</small><b>${acctMoney(credit)}</b></div><div class="card"><small>RUNNING BALANCE</small><b>${acctMoney(balance)}</b></div></div><section class="card register-card acct-ledger-card"><div class="register-heading"><div><b>Statement of account</b><span>Invoice values appear as debits; receipts and adjustments appear as credits.</span></div></div><div class="table-wrap"><table class="acct-ledger-table"><thead><tr><th>DATE</th><th>PARTICULARS</th><th>VOUCHER / REF.</th><th>DEBIT</th><th>CREDIT</th><th>BALANCE</th></tr></thead><tbody>${body}</tbody></table></div></section>${acctReminderModal()}`:''}`}
window.acctSetLedgerDates=function(from,to){acctState.ledgerFrom=from;acctState.ledgerTo=to;render()};
function acctReminderModal(){return`<div class="acct-wa-backdrop" id="acctPartyReminder" hidden onclick="if(event.target===this)this.hidden=true"><section class="acct-wa-modal"><div class="drawer-head"><div><h2>Party payment reminder</h2><span class="auth-muted">Review the number and message before opening WhatsApp.</span></div><button class="close" type="button" onclick="document.getElementById('acctPartyReminder').hidden=true">×</button></div><label>Mobile number<input id="acctWaPhone" type="tel"></label><label>Message<textarea id="acctWaMessage"></textarea></label><div class="drawer-actions"><button class="btn" onclick="document.getElementById('acctPartyReminder').hidden=true">Cancel</button><button class="btn primary" onclick="sendPartyLedgerReminder()">Open WhatsApp</button></div></section></div>`}
window.openPartyLedgerReminder=function(){const name=acctState.ledgerPartyName;if(!name)return;const party=acctParty(name),due=invoices.filter(x=>x.party===name&&x.status!=='Cancelled'&&x.status!=='Draft').reduce((sum,x)=>sum+acctInvoiceDue(x),0),open=invoices.filter(x=>x.party===name&&x.status!=='Cancelled'&&x.status!=='Draft'&&acctInvoiceDue(x)>0),company=readCompany(),lines=open.map(x=>`• ${x.no} (${acctDisplayDate(x.date)}): ${acctMoney(acctInvoiceDue(x))}`).join('\n'),message=`Dear ${name},\n\nThis is a gentle reminder that the following balances are outstanding:\n${lines||'No outstanding invoices.'}\n\nTotal outstanding: ${acctMoney(due)}\nPlease let us know once payment has been made.\n\nThank you,\n${company.name||'Accounts'}`;document.getElementById('acctWaPhone').value=party.mobile||party.phone||'';document.getElementById('acctWaMessage').value=message;document.getElementById('acctPartyReminder').hidden=false};
window.sendPartyLedgerReminder=function(){const raw=document.getElementById('acctWaPhone').value.trim(),digits=raw.replace(/\D/g,'');if(digits.length<10){toast('Enter a valid mobile number before opening WhatsApp');return}const phone=digits.length===10?'91'+digits:digits;window.open(`https://wa.me/${phone}?text=${encodeURIComponent(document.getElementById('acctWaMessage').value)}`,'_blank','noopener,noreferrer');document.getElementById('acctPartyReminder').hidden=true};
window.printPartyLedger=function(selectedOnly=false,sharePdf=false){const party=acctState.ledgerPartyName;if(!party){toast('Select a party first');return}const entries=acctLedgerTransactions(party).filter(x=>(!acctState.ledgerFrom||x.date>=acctState.ledgerFrom)&&(!acctState.ledgerTo||x.date<=acctState.ledgerTo));let chosen=entries;if(selectedOnly){const indexes=[...document.querySelectorAll('.acct-ledger-select:checked')].map(x=>Number(x.value));if(!indexes.length){toast('Select at least one ledger record to print');return}chosen=indexes.map(i=>entries[i]).filter(Boolean)}let runningBalance=0;chosen=chosen.map(x=>({...x,printBalance:runningBalance+=x.debit-x.credit}));const p=acctParty(party),c=readCompany(),debit=chosen.reduce((a,x)=>a+x.debit,0),credit=chosen.reduce((a,x)=>a+x.credit,0),net=debit-credit,side=net<0?'CR':'DR',closing=Math.abs(net),body=chosen.map(x=>`<tr><td>${acctEsc(acctDisplayDate(x.date))}</td><td>${acctEsc(x.label)}</td><td>${x.debit?acctMoney(x.debit).slice(1):''}</td><td>${x.credit?acctMoney(x.credit).slice(1):''}</td><td>${acctMoney(Math.abs(x.printBalance)).slice(1)} ${x.printBalance<0?'CR':'DR'}</td></tr>`).join('');document.getElementById('acctLedgerPrintRoot')?.remove();const root=document.createElement('div');root.id='acctLedgerPrintRoot';root.innerHTML=`<style>@media screen{#acctLedgerPrintRoot{display:none}}@media print{@page{size:A4 portrait;margin:12mm}body.acct-ledger-print-mode{background:#fff!important;margin:0!important}body.acct-ledger-print-mode>*:not(#acctLedgerPrintRoot){display:none!important}body.acct-ledger-print-mode #acctLedgerPrintRoot{display:block!important;position:static!important;width:100%!important;box-sizing:border-box!important;padding:0!important;color:#111!important;background:#fff!important;font:10pt Arial,sans-serif!important}#acctLedgerPrintRoot header{text-align:center;line-height:1.45;border-bottom:1px solid #222;padding-bottom:8px}#acctLedgerPrintRoot h2{margin:8px 0;font-size:15pt}#acctLedgerPrintRoot .ledger-print-meta{margin:10px 0;border:1px solid #222;padding:8px}#acctLedgerPrintRoot .ledger-print-meta>div{display:grid;grid-template-columns:100px 1fr 100px 1fr;gap:4px 8px}#acctLedgerPrintRoot table{width:100%;border-collapse:collapse}#acctLedgerPrintRoot th,#acctLedgerPrintRoot td{border:1px solid #222;padding:6px;text-align:left;font-size:9pt}#acctLedgerPrintRoot th{background:#f1f3f3!important;color:#111!important}#acctLedgerPrintRoot td:nth-child(n+3){text-align:right}#acctLedgerPrintRoot tfoot td{border-top:2px solid #222}}</style><header><b>${acctEsc(c.name||'')}</b><div>${acctEsc(c.gstin||'')}</div><div>${acctEsc(c.address||'')}</div><div>${acctEsc([c.city,c.pincode].filter(Boolean).join(' · '))}</div><div>${acctEsc(c.phone||c.mobile||'')}</div><h2>Ledger</h2></header><section class="ledger-print-meta"><div><b>Name</b><span>${acctEsc(p.name||party)}</span><b>Code_No</b><span>${acctEsc(p.code||p.codeNo||'')}</span><b>Page No.</b><span>1</span><b>Address</b><span>${acctEsc([p.address,p.city,p.state,p.pincode].filter(Boolean).join(', '))}</span><b>Period</b><span>${acctEsc(acctDisplayDate(acctState.ledgerFrom)||'Beginning')} to ${acctEsc(acctDisplayDate(acctState.ledgerTo)||'Today')}</span></div></section><table><thead><tr><th>DATE</th><th>Particular</th><th>Debit</th><th>Credit</th><th>Balance</th></tr></thead><tbody>${body}<tr class="ledger-print-total"><td></td><td><b>TOTAL</b></td><td><b>${acctMoney(debit).slice(1)}</b></td><td><b>${acctMoney(credit).slice(1)}</b></td><td></td></tr></tbody><tfoot><tr><td colspan="2"><b>Closing Balance</b></td><td colspan="3"><b>${acctMoney(closing).slice(1)} &nbsp; ${side}</b></td></tr></tfoot></table>`;document.body.append(root);document.body.classList.add('acct-ledger-print-mode');const cleanup=()=>{document.body.classList.remove('acct-ledger-print-mode');root.remove()};if(sharePdf){window.sharePrintPdfToWhatsApp('Party-ledger-'+(p.name||party),p.mobile||'').finally(cleanup);return}window.addEventListener('afterprint',cleanup,{once:true});window.print()};
function acctVoucherRows(){return acctReadArray('paymentVouchers').sort((a,b)=>acctDateISO(b.date).localeCompare(acctDateISO(a.date))).map(v=>`<tr><td><b>${acctEsc(v.number)}</b></td><td>${acctEsc(acctDisplayDate(v.date))}</td><td>${acctEsc(v.party)}</td><td>${acctEsc(v.method||'')}</td><td>${(v.allocations||[]).length}</td><td class="amount">${acctMoney(v.amount)}</td><td class="invoice-actions"><button type="button" onclick="openSavedPaymentVoucher('${acctEsc(v.id)}')">Open</button><button type="button" onclick="editPaymentVoucher('${acctEsc(v.id)}')">Edit</button><button type="button" class="delete-action" onclick="deletePaymentVoucher('${acctEsc(v.id)}')">Delete</button></td></tr>`).join('')||'<tr><td colspan="7" class="master-no-results">No party payment vouchers saved yet.</td></tr>'}
function acctVoucherPage(){const parties=acctParties(),party=acctState.voucherPartyName,rows=party?invoices.filter(x=>x.party===party&&x.status!=='Cancelled'&&x.status!=='Draft').map(x=>({...x,due:acctInvoiceDue(x)})).filter(x=>x.due>0).sort((a,b)=>(acctDateISO(a.date)||'').localeCompare(acctDateISO(b.date)||'')):[],opts=parties.map(p=>`<option value="${acctEsc(p.name)}" ${party===p.name?'selected':''}>${acctEsc(p.name)}${p.gstin?' · '+acctEsc(p.gstin):''}</option>`).join(''),actions='<button class="btn primary" onclick="openPaymentVoucher()">＋ New payment voucher</button>';return`${acctPageHead('REGISTERS · RECEIPTS','Payment vouchers','Record one party receipt and apply it across several open invoices.',actions)}<section class="card register-card"><div class="register-heading"><div><b>Party receipts</b><span>Each voucher allocation updates the invoice register and party ledger.</span></div><div class="acct-voucher-search"><select aria-label="Choose party to allocate a voucher" onchange="selectVoucherParty(this.value)"><option value="">Choose a party for allocation</option>${opts}</select></div></div>${party?`<div class="acct-open-invoices"><b>Open invoices for ${acctEsc(party)}</b><span>${rows.length} invoice${rows.length===1?'':'s'} with an outstanding balance</span></div>`:''}<div class="table-wrap"><table><thead><tr><th>VOUCHER</th><th>DATE</th><th>PARTY</th><th>METHOD</th><th>INVOICES ADJUSTED</th><th>RECEIVED</th><th>ACTIONS</th></tr></thead><tbody data-actions="1">${acctVoucherRows()}</tbody></table></div></section>`}
window.selectVoucherParty=function(name){const oldForm=page==='New payment voucher'?document.querySelector('.acct-voucher-form'):null,keep={};if(oldForm)for(const input of oldForm.elements)if(input.name&&input.name!=='party')keep[input.name]=input.value;acctState.voucherPartyName=name;render();if(oldForm&&page==='New payment voucher'){const form=document.querySelector('.acct-voucher-form');for(const [key,value] of Object.entries(keep)){const input=form?.elements.namedItem(key);if(input)input.value=value}window.updateVoucherTotal()}};
function acctVoucherEntryPage(){const settings=acctVoucherSettings(),name=acctState.voucherPartyName,party=acctParty(name),dueInvoices=name?invoices.filter(x=>x.party===name&&x.status!=='Cancelled'&&x.status!=='Draft').map(x=>({...x,due:acctInvoiceDue(x)})).filter(x=>x.due>0).sort((a,b)=>(acctDateISO(a.date)||'').localeCompare(acctDateISO(b.date)||'')):[],partyOptions=acctParties().map(p=>`<option value="${acctEsc(p.name)}" ${name===p.name?'selected':''}>${acctEsc(p.name)} · ${acctEsc(p.gstin||p.mobile||p.city||'')}</option>`).join('');return`${acctPageHead('REGISTERS · RECEIPTS','Party payment voucher','Allocate a single receipt across one or more open invoices.')}<form class="card setup-form acct-voucher-form" onsubmit="savePaymentVoucher(event)"><div class="setup-section"><div class="setup-section-title"><b>Voucher details</b><span>Enter the total received, then allocate it across invoices.</span></div><div class="setup-grid"><div class="field"><label>Voucher number *</label><input name="number" required value="${acctEsc(acctNextVoucherNo())}"></div><div class="field"><label>Receipt date *</label><input name="date" type="date" required value="${acctToday()}"></div><div class="field"><label>Total payment amount *</label><input name="amount" type="number" min="0.01" step="0.01" required placeholder="0.00" oninput="updateVoucherTotal()"></div><div class="field"><label>Party *</label><select name="party" required onchange="selectVoucherParty(this.value)"><option value="">Choose party</option>${partyOptions}</select></div><div class="field"><label>Payment method</label><select name="method"><option>Cash</option><option>Bank transfer</option><option>Cheque</option><option>UPI</option><option>Other</option></select></div><div class="field"><label>Transaction / cheque reference</label><input name="reference" placeholder="Optional"></div><div class="field"><label>Notes</label><input name="notes" placeholder="Optional voucher note"></div></div></div><div class="setup-section"><div class="setup-section-title"><b>Adjust invoice dues</b><span>Enter the portion of this receipt applied to each invoice.</span></div>${name?`<div class="table-wrap"><table class="acct-allocation-table"><thead><tr><th>INVOICE</th><th>DATE</th><th>INVOICE VALUE</th><th>DUE BEFORE</th><th>APPLIED NOW</th><th>DUE AFTER</th></tr></thead><tbody>${dueInvoices.map(x=>`<tr data-invoice-no="${acctEsc(x.no)}" data-due="${x.due}"><td>${acctEsc(x.no)}</td><td>${acctEsc(acctDisplayDate(x.date))}</td><td>${acctMoney(x.amount)}</td><td>${acctMoney(x.due)}</td><td><input class="acct-allocation" type="number" min="0" max="${x.due}" step="0.01" value="" placeholder="0.00" onfocus="updateVoucherTotal(this)" oninput="updateVoucherTotal(this)" aria-label="Amount applied to invoice ${acctEsc(x.no)}"></td><td class="acct-due-after">${acctMoney(x.due)}</td></tr>`).join('')||'<tr><td colspan="6" class="master-no-results">This party has no open invoices to adjust.</td></tr>'}</tbody></table></div>`:'<div class="acct-empty-note">Choose a party to list its open invoices.</div>'}<div class="acct-voucher-total"><span>Amount adjusted</span><b id="acctVoucherTotal">₹0.00</b></div><div class="acct-voucher-total"><span>Remaining unadjusted</span><b id="acctVoucherRemaining">₹0.00</b></div></div><div class="settings-footer"><button class="btn" type="button" onclick="navigate('Payment vouchers')">Cancel</button><button class="btn primary" type="submit" ${name?'':'disabled'}>Save payment voucher</button></div></form>`}
window.updateVoucherTotal=function(input){const row=input.closest('tr'),due=Number(row?.dataset.due||0),amount=Math.max(0,Math.min(due,Number(input.value)||0));if(amount!==Number(input.value||0))input.value=amount.toFixed(2);row.querySelector('.acct-due-after').textContent=acctMoney(due-amount);const total=[...document.querySelectorAll('.acct-allocation')].reduce((sum,x)=>sum+Number(x.value||0),0),target=document.getElementById('acctVoucherTotal');if(target)target.textContent=acctMoney(total)};
window.openPaymentVoucher=function(party=''){acctState.voucherPartyName=party||acctState.voucherPartyName;page='New payment voucher';render()};
window.savePaymentVoucher=function(event){event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const data=new FormData(form),party=String(data.get('party')||''),allocations=[...document.querySelectorAll('.acct-allocation')].map(input=>({invoiceNo:input.closest('tr').dataset.invoiceNo,amount:Number(input.value||0)})).filter(x=>x.amount>0);if(!allocations.length){toast('Enter an amount against at least one invoice');return}for(const a of allocations){const invoice=invoices.find(x=>x.no===a.invoiceNo),due=invoice?Math.max(0,Number(invoice.amount||0)-Number(invoice.paidAmount||0)-Number(invoice.deductionAmount||0)):0;if(!invoice||invoice.party!==party||a.amount>due+.005){toast(`Allocation for ${a.invoiceNo} exceeds its current due`);return}}const amount=Number(allocations.reduce((sum,x)=>sum+x.amount,0).toFixed(2)),rows=acctReadArray('paymentVouchers'),settings=acctVoucherSettings(),voucher={id:acctUID(),number:String(data.get('number')).trim(),date:String(data.get('date')),party,method:String(data.get('method')||''),reference:String(data.get('reference')||'').trim(),notes:String(data.get('notes')||'').trim(),amount,allocations,createdAt:new Date().toISOString()};for(const a of allocations){const invoice=invoices.find(x=>x.no===a.invoiceNo);invoice.paidAmount=Number((Number(invoice.paidAmount||0)+a.amount).toFixed(2));const due=Math.max(0,Number(invoice.amount||0)-invoice.paidAmount-Number(invoice.deductionAmount||0));invoice.status=due<=.005?'Paid':'Due'}rows.unshift(voucher);acctWriteArray('paymentVouchers',rows);settings.nextNumber=Number(settings.nextNumber||1)+1;writeScopedCompany('paymentVoucherSettings',settings);save();acctState.voucherPartyName=party;page='Payment vouchers';render();toast(`Payment voucher saved · ${acctMoney(amount)} applied to ${allocations.length} invoice${allocations.length===1?'':'s'}`)};
function acctEnhanceVoucherUI(){const listSearch=document.querySelector('.acct-voucher-search select');if(listSearch&&!listSearch.dataset.enhanced){const input=document.createElement('input');input.type='search';input.placeholder='Type party name or details';input.value=acctState.voucherPartyName;input.setAttribute('list','acctVoucherParties');input.dataset.enhanced='1';input.oninput=()=>{const match=acctParties().find(p=>p.name.toLowerCase()===input.value.trim().toLowerCase());if(match)window.selectVoucherParty(match.name)};input.onchange=()=>window.selectVoucherParty(input.value);const list=document.createElement('datalist');list.id='acctVoucherParties';list.innerHTML=acctParties().map(p=>`<option value="${acctEsc(p.name)}">${acctEsc(acctPartyDetails(p))}</option>`).join('');listSearch.replaceWith(input,list)}const rows=document.querySelector('.register-card tbody');if(rows&&!rows.dataset.actions){rows.dataset.actions='1';rows.querySelectorAll('tr').forEach(row=>{const number=row.cells[0]?.innerText.trim(),v=acctReadArray('paymentVouchers').find(x=>x.number===number);if(!v)return;const td=row.insertCell(-1);td.className='invoice-actions';td.innerHTML=`<button onclick="openSavedPaymentVoucher('${acctEsc(v.id)}')">Open</button><button onclick="editPaymentVoucher('${acctEsc(v.id)}')">Edit</button><button class="delete-action" onclick="deletePaymentVoucher('${acctEsc(v.id)}')">Delete</button>`})}const form=document.querySelector('.acct-voucher-form');if(form&&!form.dataset.enhanced){form.dataset.enhanced='1';const select=form.querySelector('select[name="party"]');if(select){const input=document.createElement('input');input.name='party';input.required=true;input.type='search';input.placeholder='Type party name or details';input.value=acctState.voucherPartyName;input.setAttribute('list','acctVoucherPartiesEntry');input.oninput=()=>{const match=acctParties().find(p=>p.name.toLowerCase()===input.value.trim().toLowerCase());if(match)window.selectVoucherParty(match.name)};const list=document.createElement('datalist');list.id='acctVoucherPartiesEntry';list.innerHTML=acctParties().map(p=>`<option value="${acctEsc(p.name)}">${acctEsc(acctPartyDetails(p))}</option>`).join('');select.replaceWith(input);form.append(list)}const grid=form.querySelector('.setup-grid');if(grid&&!grid.querySelector('[name="amount"]')){const box=document.createElement('div');box.className='field';box.innerHTML='<label>Total received *</label><input name="amount" type="number" min="0.01" step="0.01" required oninput="updateVoucherTotal()">';grid.insertBefore(box,grid.children[3]||null)}}}
